@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* @nizivo/react/css/select.css (ARCHITECTURE.md §8.2–§8.4, §12.1; figma/13 §4.3, figma/14 §4). The
   trigger is the Select skin NativeSelect repeats (same box, border, sizes, invalid and disabled
   looks). The popup and its rows follow Figma's Select Menu 7356:406, Select Option set 7356:401,
   Group Label 7356:402 and Divider 7356:404 (M36), with one kept deviation: the selected row keeps
   the bg/brand-subtle tint. Menu (the Dropdown Menu 746:204) keeps its own look. Sizes and states
   set only privates; public
   --nz-select-* hooks are read once, at the property. Invalid reads [data-invalid], set when a
   message is presented, never :invalid (§8.3). The trigger is Label/M, or Label/L under a coarse
   pointer (M25), as NativeSelect's, so swapping one for the other does not change the text. */
@layer nz.components {
  .nz-select-trigger {
    --_nz-select-height: var(--nz-size-control-md);
    --_nz-select-radius: var(--nz-radius-md);
    --_nz-select-border: var(--nz-border-control);
    --_nz-select-border-hover: var(--nz-border-control-hover);
    --_nz-select-halo: var(--nz-focus-halo);
    --_nz-select-font: var(--nz-font-label-m);

    display: inline-flex;
    align-items: center;
    gap: var(--nz-space-2);
    /* the same box with or without a page reset (§8.1) */
    box-sizing: border-box;
    min-inline-size: 0;
    block-size: var(--nz-select-height, var(--_nz-select-height));
    padding-inline: var(--nz-space-3);
    border: var(--nz-border-width-default) solid var(--nz-select-border, var(--_nz-select-border));
    border-radius: var(--nz-select-radius, var(--_nz-select-radius));
    background: var(--nz-select-bg, var(--nz-bg-surface));
    color: var(--nz-text-primary);
    font: var(--_nz-select-font);
    cursor: pointer;
    transition:
      border-color var(--nz-duration-fast) var(--nz-easing-standard),
      box-shadow var(--nz-duration-fast) var(--nz-easing-standard);

    @media (hover: hover) {
      &:hover:not([data-disabled], :disabled) {
        border-color: var(--nz-select-border-hover, var(--_nz-select-border-hover));
      }
    }

    /* the outline lives in nz.base; this adds only the decorative halo, critical while invalid, as
       on Input and NativeSelect */
    &:is(:focus-visible, [data-focus-visible]) {
      box-shadow: 0 0 0 calc(var(--nz-border-width-focus) + 4px) var(--_nz-select-halo);
    }

    &[data-invalid] {
      --_nz-select-border: var(--nz-border-critical);
      --_nz-select-border-hover: var(--nz-border-critical);
      --_nz-select-halo: var(--nz-focus-halo-critical);
    }

    /* the Select's own flag, or a disabled Fieldset, which disables the <button> natively */
    &:is([data-disabled], :disabled) {
      --_nz-select-border: var(--nz-border-subtle);

      background: var(--nz-bg-disabled);
      color: var(--nz-text-disabled);
      cursor: not-allowed;
    }

    &[data-size='sm'] {
      --_nz-select-height: var(--nz-size-control-sm);
      --_nz-select-radius: var(--nz-radius-sm);
    }

    &[data-size='lg'] {
      --_nz-select-height: var(--nz-size-control-lg);
    }

    /* at every size, value and placeholder (inherited); the height stays on the size scale */
    @media (pointer: coarse) {
      --_nz-select-font: var(--nz-font-label-l);
    }
  }

  /* a long value ends in an ellipsis before the chevron, as NativeSelect's does */
  .nz-select-value {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    text-align: start;
    text-overflow: ellipsis;
    white-space: nowrap;

    &[data-placeholder] {
      color: var(--nz-text-tertiary);
    }
  }

  .nz-select-icon,
  .nz-select-chevron {
    display: inline-flex;
    flex: none;
    /* internal glyphs are 1em: size them to the 16 px icon slot, not to the value font */
    font-size: var(--nz-size-icon-sm);
    color: var(--nz-text-secondary);
  }

  /* one overlay band, ordered by DOM (§12.1 L1). Popups enter on the spring pair from the trigger
     side and exit on the fade (§12.2 Motion, §13.3; the Dropdown Menu master's "scale 0.96 → 1 +
     fade"); the opacity reuses the spring's duration, which stays 120 ms when reduced, so the fade
     survives reduced motion and the scale does not travel (--nz-scale-enter is 1). */
  .nz-select-popup {
    z-index: var(--nz-z-overlay);
    /* the minimum is the whole popup, border included, so it matches the trigger (§8.1) */
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-inline-size: var(--nz-trigger-width);
    max-block-size: var(--nz-available-height);
    overflow: auto;
    border: var(--nz-border-width-default) solid var(--nz-border-subtle);
    border-radius: var(--nz-radius-md);
    background: var(--nz-bg-surface-raised);
    box-shadow: var(--nz-elevation-4);
    transform-origin: var(--nz-transform-origin);
    transition:
      scale var(--nz-duration-spring) var(--nz-easing-spring),
      opacity var(--nz-duration-spring) var(--nz-easing-enter);

    &[data-entering] {
      opacity: 0;
      scale: var(--nz-scale-enter);
    }

    &[data-exiting] {
      opacity: 0;
      transition: opacity var(--nz-duration-fade) var(--nz-easing-exit);
    }
  }

  /* the listbox: the Select Menu's 6 px padding; rows touch (gap 0) */
  .nz-select-list,
  .nz-select-group {
    display: flex;
    flex-direction: column;
  }

  .nz-select-list {
    padding: var(--nz-space-1-5);
    outline: none;
  }

  /* the Select Option: 8 / 12 px, Label/M, 36 px with or without a page reset (the minimum
     includes the padding). The rows stay 14 px under a coarse pointer: they are not text fields. */
  .nz-select-item {
    display: flex;
    align-items: center;
    gap: var(--nz-space-2);
    box-sizing: border-box;
    min-block-size: 2.25rem;
    padding-block: var(--nz-space-2);
    padding-inline: var(--nz-space-3);
    border-radius: var(--nz-radius-sm);
    color: var(--nz-text-primary);
    font: var(--nz-font-label-m);
    letter-spacing: var(--nz-tracking-label-m);
    cursor: default;

    /* a pointer hint only (1.08:1 on the surface); keyboard focus is the generated ring */
    &[data-highlighted] {
      background: var(--nz-bg-hover);
    }

    /* Figma's Selected option is Label/M Strong in text/primary with a trailing check; code keeps
       the brand-subtle tint as well (M36). The check and the weight, not the colour, carry the
       state (WCAG 1.4.1). Same tracking as Label/M, so only the weight changes. */
    &[data-selected] {
      background: var(--nz-bg-brand-subtle);
      font: var(--nz-font-label-m-strong);
    }

    /* under the pointer it swaps to the hover fill and keeps the strong label and the check */
    &[data-selected][data-highlighted] {
      background: var(--nz-bg-hover);
    }

    &[data-disabled] {
      color: var(--nz-text-disabled);
      cursor: not-allowed;
    }
  }

  .nz-select-item-indicator {
    display: inline-flex;
    flex: none;
    margin-inline-start: auto;
    font-size: var(--nz-size-icon-sm);
    color: var(--nz-icon-brand);
    visibility: hidden;
  }

  .nz-select-item[data-selected] > .nz-select-item-indicator {
    visibility: visible;
  }

  /* the Select Group Label: Label/S in text/secondary, 8 / 12 / 4 / 12 */
  .nz-select-group-label {
    padding-block: var(--nz-space-2) var(--nz-space-1);
    padding-inline: var(--nz-space-3);
    color: var(--nz-text-secondary);
    font: var(--nz-font-label-s);
    letter-spacing: var(--nz-tracking-label-s);
  }

  /* the Select Divider: inset by the list padding, 4 px above and below */
  .nz-select-separator {
    flex: none;
    block-size: var(--nz-border-width-default);
    margin-block: var(--nz-space-1);
    background: var(--nz-border-subtle);
  }

  @media (forced-colors: active) {
    .nz-select-popup {
      border: 1px solid CanvasText;
    }

    /* base.css's [data-selected] floor (Highlight) loses to the fills above, a later layer, and its
       forced-color-adjust: none would then leave HighlightText on a token colour. Keyboard focus
       opens on the selected item, so repeat the floor here (§8.5); the second selector outranks the
       selected-and-highlighted hover fill, as Menu's does (week 5 visual lane). */
    .nz-select-item[data-selected],
    .nz-select-item[data-selected][data-highlighted] {
      background: Highlight;
      color: HighlightText;
      /* forced-color-adjust is inherited: the ring and the check need system colours too. The rows
         carry data-focus-inset, so the keyboard ring is drawn inside the Highlight fill, where
         HighlightText shows (CanvasText there was about 1.9:1 against the fill: week 6 review) */
      outline-color: HighlightText;
      /* one ring width further in, so Highlight shows on both sides of it: at the row's edge it
         would sit against the Canvas around the row and read as the fill shrinking */
      outline-offset: calc(-2 * var(--nz-border-width-focus));
      forced-color-adjust: none;

      & > .nz-select-item-indicator {
        color: HighlightText;
      }
    }

    /* the options are divs with aria-disabled, which the browser does not grey out */
    .nz-select-item[data-disabled] {
      color: GrayText;
    }

    .nz-select-separator {
      background: CanvasText;
    }
  }
}
